import{_ as p,o as t,c as e,a3 as l}from"./chunks/framework.DdpBa4_E.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/77-如何面对安全感建立的失败？.md","filePath":"books/attached/77-如何面对安全感建立的失败？.md","lastUpdated":1794298621000}'),_={name:"books/attached/77-如何面对安全感建立的失败？.md"};function i(o,a,r,s,n,d){return t(),e("div",null,[...a[0]||(a[0]=[l('<h3 id="如何面对安全感建立的失败" tabindex="-1">如何面对安全感建立的失败？ <a class="header-anchor" href="#如何面对安全感建立的失败" aria-label="Permalink to &quot;如何面对安全感建立的失败？&quot;">​</a></h3><p>你是否想过，即使自己非常努力地想要逃离亲密关系陷阱和不安全感的恶性循环，却还是于事无补？这种情况可能是因为伴侣一方或双方的改变动机不够强烈，从而导致努力功亏一篑。我们知道，当人们处于焦虑——回避型关系中，特别是两人都没有能力给对方足够的安全感时，生活中就会出现长久而巨大的分歧，要做到完全消退是非常困难的。但我们仍然应该相信知识就是力量。相关的依恋只是可以帮助人们了解，现在遇到的困境关乎伴侣双方，而不仅仅是一方的不可理喻，而这种困境的存在，只因为双方的分歧积累已久。</p><p>这种全新的视角所带来的最大好处就是，你会对自己有更清晰的认知。亲密关系的不协调，对于非回避型依恋风格的一方来说是非常痛苦的，他们将长期处于被回避型一方抗拒的状态。我们在书中提到的很多例子，都证实了这种情况。比如有人一直保持高度的神秘感，还反过来责怪对方过分猜忌；青睐于和伴侣分床睡，甚至找些借口不和对方待在一起。跟回避型伴侣在一起，就会长时间体验到抗拒和疏远。刚开始体验到这种疏远策略时，回避型人群的伴侣们会归咎于自己，甚至坚信对方要是换做和别的人在一起，就不会这样做了。相比自己，对方更愿意和其他的人共同生活，会开始感觉自己丧失了吸引力，变得一无是处。</p><p>而你长此以往这样想，就形成了一种潜台词：对方真的不能被你感化，同时也会对自己的角色产生颠覆性的认知。当你认识到伴侣长期的撤退策略、保持距离只是寻找舒适区的一种方式，不管对谁都是这样的时候，你就不会在关系中出现任何问题时，都把责任归咎于自身了。</p><p>起码从表面上来看，回避型的人在亲密关系中，比较不容易受伤，因为撤退毕竟是一种单方面的行为，并不需要另一方的配合。虽然回避型的一方显得更加从容，但值得注意的是，冷漠并不意味着安全感。回避型人群不断地压抑自己的亲密需求，却在亲密关系中表现出愉悦感的骤降。与此同时，他们会将自己的不快乐，归咎于伴侣头上。</p><p>那么，意识到这一点后，我们又该怎么做呢？</p><p>在接受我们的访问时，阿兰娜（Alana）讲述了她和前夫斯坦（Stan）的故事。她着重强调了斯坦工作特别忙，就连周末也会有各种杂事要处理，根本很难和她待在一起，即便如此，两人的生活倒也安稳。但当阿兰娜为了拉近彼此的距离，想与斯坦来场浪漫的散步。每到这时，斯坦总是找各种借口推脱。他们不止一次遇到这种情况，阿兰娜兴致勃勃地跟朋友和同事说，自己要和斯坦出去度周末。她非常激动地制定计划，甚至开始收拾行李。而过几天，她会非常沮丧地跟朋友们打电话，说事情在最后一刻出了变故，他们就去不成了。有一次是因为斯坦的工作，有一次是他不舒服，还有一次是说车子需要修理。他们会因此大吵一架，但事情很快平息以后，下一次又要重蹈覆辙。对于阿兰娜来说，让她的希望一次又一次地落空，实在是种非常深的伤害。</p><p>最终，阿兰娜和斯坦的关系难以为继。事实上，她从来没办法掌控两人的关系，不仅仅表现在是否出去度假，甚至也不完全关乎两人是否浪漫。关键在于两人之间相隔着巨大的鸿沟，虽然阿兰娜深知这一点，但还是很难完全接受，并且带着这种分歧继续生活。</p><p>当然，也有一些人找到了在亲密需求相左的情况下，达成相对和谐局面的方法。这又是怎么做到的呢？毕竟他们都很清楚，涉及关系中某些特定方面，是很难要求对方做出颠覆性改变的。如果彼此非要强求，那就会产生西西弗斯（Sisyphean）的悲剧，所有的失落和挫败都会堆积如山，争执下去只能两败俱伤。但是换个角度，他们选择了改变自己的期望，他们学会了接受对方的一些局限，开始选择一些实用的生活策略，比如下面这样：</p><ul><li><p>学着一定程度上的独处，就算伴侣不是个主动的人，也不会催促他们改变。</p></li><li><p>伴侣抗击亲密接触时，他们会把这当作伴侣的天性并且接受，而不再采取自我贬低和攻击行为。</p></li><li><p>即使原本非常期待和伴侣一起完成的事，也学着接纳可能的变数，自己独立完成。</p></li><li><p>即使伴侣不会参与，也会找一些志趣相投的朋友一同玩耍。</p></li><li><p>学会感恩伴侣的付出，同时也不计较伴侣的疏忽。</p></li></ul><p>其实有许多人都会在关系伊始，遇到伴侣之间亲密需求有冲突的问题，但他们最终选择了改变自己的心态，达成了一个两人都可以接受的平衡状态，比如下面的例子：</p><ul><li><p>53岁的道格（Doug）曾经因为妻子的晚归，两人常常吵得不可开交，而最终他决定换种方式来应对。晚上妻子进门的时候，他不再暴怒而是报以温柔的问候。不仅如此，他还立誓要把家打造成为令妻子归心似箭的港湾，而非战火纷飞的地狱。</p></li><li><p>38岁的娜塔莉亚（Natalia）总是梦想着与丈夫共度惬意时光，因为丈夫对共度周末的屡屡推脱，一年多的时间里，他们都争吵不休。这令她下决心改变。她开始事先列好计划，万一丈夫难得想要参加，就一起去，就算不愿意，娜塔莉亚也会从容道别，独自享受。</p></li><li><p>43岁的詹尼斯（Janis）在与拉里（Larry）结婚前，拉里就已经有过一段婚姻。他在孩子的教育上很不上心，而詹尼斯不仅要操心孩子，还要处理其他的生活琐事。她非常清楚这些事务需要自己完成，不再对丈夫的帮助抱有太强烈的期望。也不再因为他不愿协助而暴怒争吵了。</p></li></ul><p>在以上的案例中，主人公都与伴侣存在着长时间的亲密需求冲突。他们选择在亲密度上做出一些妥协，也为双方的分歧找到了自己的解决办法。这种妥协也无可厚非，都是单方面做出的，也没有涉及原则底线。重要的是，可以避免无休止的冲突，而这些冲突除了导致极大的挫败与失望，不会有任何的好处。他们在自己可以容忍的范围内选择了降低期待，有效地化解了冲突。</p>',13)])])}const h=p(_,[["render",i]]);export{u as __pageData,h as default};
